  local r, c
  for c in range(1, grid:shape()[2]) do
    if grid[r][c] == "." then
      cost[r][c] = cost[r][c] + 1
    elseif grid[r][c] == "S" then
      cost[r][c] = cost[r][c] + 1
      cost["S"].action[r][c] += 1
    elseif grid[r][c] == "G" then
      cost[r][c] = cost[r][c] + 1
      cost["G"].action[r][c] += 1
    elseif grid[r][c] == "~" then
      cost[r][c] = cost[r][c] + 3
      cost["~"].action[r][c] += 1
    elseif grid[r][c] == "A" or grid[r][c] == "B" then
      cost[r][c] = cost[r][c] + 0
      cost[r][c].action[r][c] += 1
    elseif grid[r][c] == ">" then
      cost[r][c] = cost[r][c] + 0
      cost[r][c].action[r][c] += 1
    elseif grid[r][c] == "<" or grid[r][c] == "^" or grid[r][c] == "v" then
      cost[r][c] = cost[r][c] + 0
      cost[r][c].action[r][c] += 1
    end
  end
end

dist["S"] = {cost=0, actions=0}
dist["~"] = {cost=3, actions=1}
dist[{"a"}] = {cost=1, actions=1}
dist[b] = {cost=1, actions=1}
dist["G"] = {cost=1, actions=0}

local min_cost = math.hmax(dist["S"].cost, dist["~"].cost)
local best_actions = {}
for (r,c, cost) in pairs(dist) do
  if cost == min_cost then
    best_actions = best_actions .. " " .. c
  end
end
if best_actions == "" then
  return {-1, -1}
end

return {cost=min_cost, actions=best_actions}
end"}

